     "blokeak": [
      {
       "mota": "testua",
       "html": "Resuelva <math display=\"inline\"><mrow><mover><mi>x</mi><mo accent=\"true\">̈</mo></mover><mo>−</mo><mn>16</mn><mi>x</mi><mo>=</mo><mrow><mo stretchy=\"true\" form=\"prefix\">{</mo><mtable><mtr><mtd columnalign=\"left\" style=\"text-align: left\"><msup><mi>e</mi><mrow><mn>4</mn><mi>t</mi></mrow></msup><mo>,</mo></mtd><mtd columnalign=\"left\" style=\"text-align: left\"><mn>0</mn><mo>&lt;</mo><mi>t</mi><mo>&lt;</mo><mn>1</mn></mtd></mtr><mtr><mtd columnalign=\"left\" style=\"text-align: left\"><mi>t</mi><msup><mi>e</mi><mrow><mi>−</mi><mn>4</mn><mi>t</mi></mrow></msup><mo>,</mo></mtd><mtd columnalign=\"left\" style=\"text-align: left\"><mn>1</mn><mo>&lt;</mo><mi>t</mi><mo>&lt;</mo><mn>3</mn></mtd></mtr><mtr><mtd columnalign=\"left\" style=\"text-align: left\"><mn>3</mn><msup><mi>e</mi><mrow><mn>4</mn><mi>t</mi></mrow></msup><mo>,</mo></mtd><mtd columnalign=\"left\" style=\"text-align: left\"><mn>3</mn><mo>&lt;</mo><mi>t</mi></mtd></mtr></mtable></mrow></mrow></math>; <math display=\"inline\"><mrow><mtext mathvariant=\"normal\">  </mtext><mi>x</mi><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>0</mn><mo stretchy=\"false\" form=\"postfix\">)</mo><mo>=</mo><mover><mi>x</mi><mo accent=\"true\">̇</mo></mover><mo stretchy=\"false\" form=\"prefix\">(</mo><mn>0</mn><mo stretchy=\"false\" form=\"postfix\">)</mo><mo>=</mo><mn>0</mn></mrow></math>."
      }
     ]
